    attach:"保元大成汤 （《外科正宗》） 人参 白术 黄芪蜜水拌\n炒，各二钱（各6g） 茯苓 白芍 陈皮 归身 甘草炙 附子 山萸\n肉 五味子各一钱（各3g） 木香 砂仁各五分（各1.5g） 水二盅，煨\n姜三片去皮，大枣三枚，煎八分，食远服。功用：益气温阳，生肌敛\n疮。主治：胃气将绝，元阳衰微之溃疡。症见睡卧昏倦，足冷身凉，便\n溏或秘，胸膈或宽或不宽，食而无味，舌润少津，脉虚细。",
